//! Characterization snapshots: every example under `examples/`, generated by the `isoloom` binary
//! on every target, one snapshot per example × target (`snapshots/examples/<example>__<target>.snap`).
//!
//! They freeze what `generate` writes today, so a change to the output is always deliberate and
//! reviewed (`cargo insta test --review`). A generated target's snapshot holds the target's line
//! from `isoloom targets`, what `generate --target` printed, then every file it wrote, sorted by
//! path, each under a `## <path>` header. A refused target's snapshot holds the refusal: the
//! `isoloom targets` reason and `generate`'s message.
//!
//! Each run copies the example, without any generated `.isoloom/` outputs, into a fresh folder,
//! and runs the binary with an empty `ISOLOOM_HOME` and no other `ISOLOOM_*` variable, so the
//! user's defaults and profile never leak in. A file a target shares with an earlier target of the
//! same example (the Compose file under `docker-vm`, `resolved.json` everywhere), byte for byte,
//! is written once, in the earlier snapshot; the later one names it and says where it is.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // helpers outside #[test] functions too: a failing test is the report.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use isoloom_spec::Target;

/// What a project folder holds: each file's path (with `/`, relative to the folder) and bytes.
type Tree = BTreeMap<String, Vec<u8>>;

/// The folders an example may hold that aren't the project: generated outputs and tool state.
fn skipped(name: &str) -> bool {
    name == ".isoloom" || name.starts_with(".isoloom-") || name == ".vagrant" || name == ".terraform"
}

/// Every file under `dir`; with `projects_only`, without the skipped folders.
fn read_tree(dir: &Path, projects_only: bool) -> Tree {
    let mut tree = Tree::new();
    let mut stack = vec![(dir.to_path_buf(), String::new())];
    while let Some((at, prefix)) = stack.pop() {
        for entry in std::fs::read_dir(&at).unwrap() {
            let entry = entry.unwrap();
            let name = entry.file_name().to_string_lossy().into_owned();
            let rel = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
            if !entry.file_type().unwrap().is_dir() {
                tree.insert(rel, std::fs::read(entry.path()).unwrap());
            } else if !(projects_only && skipped(&name)) {
                stack.push((entry.path(), rel));
            }
        }
    }
    tree
}

/// Writes `tree` under `dir`.
fn write_tree(dir: &Path, tree: &Tree) {
    for (rel, bytes) in tree {
        let path = dir.join(rel);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, bytes).unwrap();
    }
}

/// Runs `isoloom <args>` with `home` as its only Isoloom setting.
fn isoloom(home: &Path, args: &[&str]) -> Output {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_isoloom"));
    for (key, _) in std::env::vars_os() {
        if key.to_string_lossy().starts_with("ISOLOOM_") {
            cmd.env_remove(key);
        }
    }
    cmd.args(args).env("ISOLOOM_HOME", home).output().unwrap()
}

/// What a command printed, stdout then stderr, with `dir` and `home` named, not spelled out.
fn printed(o: &Output, dir: &Path, home: &Path) -> String {
    let all = format!("{}{}", String::from_utf8_lossy(&o.stdout), String::from_utf8_lossy(&o.stderr));
    normalize(&all, dir, home)
}

/// `text` with the run's folders as placeholders and LF line endings, so it reads the same on
/// every host. A folder's canonical path goes first: the temp folder's can be longer (macOS's
/// `/private/var/...` for `/var/...`).
fn normalize(text: &str, dir: &Path, home: &Path) -> String {
    let mut text = text.replace("\r\n", "\n");
    for (path, placeholder) in [(dir, "<project>"), (home, "<home>")] {
        if let Ok(canonical) = path.canonicalize() {
            text = text.replace(&canonical.display().to_string(), placeholder);
        }
        text = text.replace(&path.display().to_string(), placeholder);
    }
    text
}

/// The target's block in `isoloom targets`: its `✓`/`✗` line, and the lines indented under it
/// (the clouds `cloud-vm` refuses).
fn target_block(listing: &str, id: &str) -> String {
    let mut block = String::new();
    let mut inside = false;
    for line in listing.lines() {
        if let Some(rest) = line.strip_prefix("✓ ").or_else(|| line.strip_prefix("✗ ")) {
            inside = rest.split(' ').next() == Some(id);
        } else if !line.starts_with("    ") {
            inside = false;
        }
        if inside {
            block.push_str(line);
            block.push('\n');
        }
    }
    assert!(!block.is_empty(), "`isoloom targets` doesn't list {id}:\n{listing}");
    block
}

/// A file's contents as the snapshot shows them: its text, or a fingerprint of its bytes.
fn shown(bytes: &[u8], dir: &Path, home: &Path) -> String {
    std::str::from_utf8(bytes).map_or_else(|_| fingerprint(bytes), |text| normalize(text, dir, home))
}

/// A binary file as the snapshot shows it: its size and FNV-1a hash (stable, no dependency).
fn fingerprint(bytes: &[u8]) -> String {
    let hash = bytes
        .iter()
        .fold(0xcbf2_9ce4_8422_2325_u64, |h, b| (h ^ u64::from(*b)).wrapping_mul(0x0100_0000_01b3));
    format!("({} bytes, not UTF-8, FNV-1a {hash:016x})\n", bytes.len())
}

/// One example, generated on every target: the snapshots, in `Target::ALL` order.
struct Example {
    name: String,
    snapshots: Vec<(Target, String)>,
}

/// The files of one example already written into an earlier target's snapshot: path, then the
/// bytes and the target whose snapshot holds them.
type Seen = BTreeMap<String, (Vec<u8>, Target)>;

/// The snapshot of one target: the example (its files, `source`) generated in a fresh copy under
/// `work`. `listing` is what `isoloom targets` printed for it.
fn snapshot(work: &Path, source: &Tree, listing: &str, target: Target, seen: &mut Seen) -> String {
    let dir = work.join(target.id());
    let home = work.join(format!("home-{}", target.id()));
    write_tree(&dir, source);
    std::fs::create_dir_all(&home).unwrap();
    let o = isoloom(&home, &["generate", dir.to_str().unwrap(), "--target", target.id()]);
    let code = o.status.code().map_or_else(|| "signal".to_string(), |c| c.to_string());
    let mut out = String::new();
    writeln!(out, "# isoloom targets\n{}", target_block(listing, target.id())).unwrap();
    writeln!(out, "# isoloom generate --target {} (exit {code})\n{}", target.id(), printed(&o, &dir, &home)).unwrap();
    let written: Tree = read_tree(&dir, false)
        .into_iter()
        .filter(|(rel, bytes)| source.get(rel) != Some(bytes))
        .collect();
    for (rel, bytes) in written {
        match seen.get(&rel) {
            Some((before, owner)) if *before == bytes => {
                writeln!(out, "## {rel}: identical in the `{}` snapshot\n", owner.id()).unwrap();
            }
            _ => {
                writeln!(out, "## {rel}\n{}", shown(&bytes, &dir, &home)).unwrap();
                seen.insert(rel, (bytes, target));
            }
        }
    }
    out
}

/// Every target's snapshot for the example in `dir`, generated under `work`.
fn generate_example(dir: &Path, work: &Path) -> Example {
    let name = dir.file_name().unwrap().to_string_lossy().into_owned();
    let source = read_tree(dir, true);
    let listed = work.join("listed");
    let home = work.join("home-listed");
    write_tree(&listed, &source);
    std::fs::create_dir_all(&home).unwrap();
    let o = isoloom(&home, &["targets", listed.to_str().unwrap()]);
    let listing = printed(&o, &listed, &home);
    assert!(o.status.success(), "{name}: `isoloom targets` failed:\n{listing}");
    let mut seen = Seen::new();
    let snapshots = Target::ALL.into_iter().map(|t| (t, snapshot(work, &source, &listing, t, &mut seen))).collect();
    Example { name, snapshots }
}

/// The example folders, by name.
fn examples() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../examples");
    let mut dirs: Vec<PathBuf> = std::fs::read_dir(&root)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.join("isoloom.yml").is_file())
        .collect();
    dirs.sort();
    dirs
}

#[test]
fn every_example_on_every_target() {
    let scratch = std::env::temp_dir().join(format!("isoloom-example-snapshots-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&scratch);
    let dirs = examples();
    assert!(!dirs.is_empty(), "no example found");
    // One thread per example (each runs the binary once per target); snapshots are asserted in
    // order afterwards.
    let generated: Vec<Example> = std::thread::scope(|s| {
        let handles: Vec<_> = dirs
            .iter()
            .map(|dir| {
                let work = scratch.join(dir.file_name().unwrap());
                s.spawn(move || generate_example(dir, &work))
            })
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    let _ = std::fs::remove_dir_all(&scratch);
    let mut settings = insta::Settings::clone_current();
    settings.set_snapshot_path("snapshots/examples");
    settings.set_prepend_module_to_snapshot(false);
    settings.set_omit_expression(true);
    settings.bind(|| {
        for example in &generated {
            for (target, contents) in &example.snapshots {
                insta::assert_snapshot!(format!("{}__{}", example.name, target.id()), contents);
            }
        }
    });
}
